		return herdrError(err)
	}
	if _, err := s.herdrCall(ctx.Context, "workspace.rename", map[string]any{"workspace_id": pane.WorkspaceID, "label": leadWorkspaceLabel(project)}); err != nil {
		return herdrError(err)
	}
